{
  "name": "ddl_snapshot",
  "description": "DDL of a synced database (schemas, extensions, enum/domain types, sequences, tables with defaults, identity, constraints, indexes, comments, functions, procedures, views in order, triggers) for tests: all of it, or only some tables, functions or what a service uses, closed over what they need (FK targets, trigger functions, called functions and their tables). With workspace, written to <module>/src/test/resources/dt-schema/<db>.sql (or path).",
  "group": "code",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "env": {
        "type": "string",
        "enum": [
          "dev",
          "fixture"
        ],
        "default": "dev",
        "description": "Environment"
      },
      "db": {
        "type": "string",
        "description": "Database name from the env"
      },
      "tables": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Tables (schema.name or name)"
      },
      "functions": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Functions/procedures"
      },
      "service": {
        "type": "string",
        "description": "A service: the objects its passport uses in this db"
      },
      "workspace": {
        "type": "string",
        "description": "Write it into this workspace"
      },
      "path": {
        "type": "string",
        "description": "File path in the workspace"
      }
    },
    "required": [
      "db"
    ]
  }
}
